        df['gender_mf_num'] = pd.to_numeric(df['gender_mf'], errors='coerce')
        formula_ols_gender = 'log_alldeaths ~ gender_mf_num' + base_controls
        ols_gender = smf.ols(formula_ols_gender, data=df).fit()
        results['ols_gender'] = ols_gender
